/* Real-prompt explorer and per-question before/after grid. Reads window.EXAMPLES (generated by make_examples.py). */
(function () {
  "use strict";
  var X = window.EXAMPLES;
  if (!X) { return; }
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text != null) { n.textContent = text; }
    return n;
  }
  function fmt(v, d) { var s = Math.abs(v).toFixed(d == null ? 3 : d); return (v < 0 && +s !== 0 ? "−" : "") + s; }
  function kOf2(acc) { return Math.round(acc * 2) + " of 2"; }

  /* ---------- one prompt pair: wrapper text highlighted, shared question muted ---------- */
  function renderPair(segs, names, opts) {
    var box = el("div", "pair");
    var shared = segs[1][0];
    [0, 1].forEach(function (side) {
      var pane = el("div", "pane " + (side === 0 ? "pane-eval" : "pane-depl"));
      var head = el("div", "pane-head");
      head.appendChild(el("span", "sw " + (side === 0 ? "sw-eval" : "sw-depl")));
      head.appendChild(document.createTextNode(names[side]));
      var body = el("pre", "prompt");
      var pre = el("span", "wrapper", segs[0][side]);
      var mid = el("span", "shared", shared);
      var post = el("span", "wrapper", segs[2][side]);
      body.appendChild(pre); body.appendChild(mid); body.appendChild(post);
      pane.appendChild(head); pane.appendChild(body);
      box.appendChild(pane);
    });
    if (opts && opts.collapsible) { box.classList.toggle("collapsed", !!opts.collapsed); }
    return box;
  }

  /* ---------- part 1: tabs over one real pair per behavior ---------- */
  var pairRoot = document.getElementById("pair-explorer");
  if (pairRoot) {
    var tabs = el("div", "seg", null); tabs.setAttribute("role", "tablist"); tabs.setAttribute("aria-label", "Behavior");
    var stage = el("div", "pair-stage");
    var meta = el("div", "pair-meta");
    var toggle = el("button", "pill ghost", "Hide the shared question");
    toggle.type = "button"; toggle.setAttribute("aria-pressed", "false");
    var tabBtns = [], current = 0, collapsed = false;
    function showPair(i) {
      current = i;
      tabBtns.forEach(function (b, k) { b.setAttribute("aria-selected", k === i ? "true" : "false"); b.tabIndex = k === i ? 0 : -1; });
      var p = X.pairs[i];
      stage.innerHTML = ""; meta.innerHTML = "";
      var pair = renderPair(p.segments, [p.eval_name, p.deploy_name]);
      pair.classList.toggle("collapsed", collapsed);
      pair.classList.add("enter");
      stage.appendChild(pair);
      meta.appendChild(el("p", "pair-note", p.note));
      if (p.outcome) {
        var o = p.outcome;
        var line = el("p", "outcome");
        line.innerHTML = "<strong>What the checkpoint did on this question.</strong> Correct answers, counted over the two templates of each framing: "
          + "evaluation framing " + kOf2(o.base_eval) + " before the clamp and " + kOf2(o.clamp_eval) + " after; "
          + "deployment framing " + kOf2(o.base_deploy) + " before and " + kOf2(o.clamp_deploy) + " after. The prompts above are one template per framing.";
        meta.appendChild(line);
      }
      var src = el("p", "src"); src.appendChild(el("span", null, "Source: ")); src.appendChild(el("code", null, p.source));
      meta.appendChild(src);
    }
    X.pairs.forEach(function (p, i) {
      var b = el("button", null, p.label); b.type = "button"; b.setAttribute("role", "tab");
      b.addEventListener("click", function () { showPair(i); });
      b.addEventListener("keydown", function (e) {
        var k = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
        if (k) { var n = (i + k + X.pairs.length) % X.pairs.length; showPair(n); tabBtns[n].focus(); e.preventDefault(); }
      });
      tabBtns.push(b); tabs.appendChild(b);
    });
    toggle.addEventListener("click", function () {
      collapsed = !collapsed;
      toggle.setAttribute("aria-pressed", collapsed ? "true" : "false");
      toggle.textContent = collapsed ? "Show the shared question" : "Hide the shared question";
      var pr = stage.querySelector(".pair"); if (pr) { pr.classList.toggle("collapsed", collapsed); }
    });
    var bar = el("div", "viz-head");
    var legend = el("div", "legend");
    legend.innerHTML = '<span><i class="sw wrapper-sw"></i>Wrapper (differs)</span><span><i class="sw shared-sw"></i>Question and options (identical)</span>';
    bar.appendChild(tabs); bar.appendChild(toggle);
    pairRoot.appendChild(bar); pairRoot.appendChild(legend); pairRoot.appendChild(stage); pairRoot.appendChild(meta);
    showPair(0);
  }

  /* ---------- part 2: 200 questions, before and after the clamp ---------- */
  var gridRoot = document.getElementById("item-grid");
  if (gridRoot) {
    var G = X.grid;
    var defs = {
      restored: "The clamp closes the gap and both framings reach the leading framing’s accuracy.",
      homogenized: "The clamp closes the gap, but both framings fall to the trailing framing’s accuracy.",
      persistent: "The clamp does not close the gap.",
      no_gap: "No baseline gap to close (gap of 0.1 or less)."
    };
    var names = { restored: "Restored", homogenized: "Homogenized", persistent: "Persistent", no_gap: "No baseline gap" };
    var phase = "before", selected = 0, cols = [], timer = null;

    var ctl = el("div", "viz-head");
    var seg = el("div", "seg"); seg.setAttribute("role", "group"); seg.setAttribute("aria-label", "Intervention state");
    var bBefore = el("button", null, "Before the clamp"), bAfter = el("button", null, "After the clamp");
    [bBefore, bAfter].forEach(function (b) { b.type = "button"; seg.appendChild(b); });
    var play = el("button", "pill", "Replay"); play.type = "button";
    var lg = el("div", "legend");
    lg.innerHTML = '<span><i class="sw sw-eval sq"></i>Top tile: evaluation framing</span><span><i class="sw sw-depl sq"></i>Bottom tile: deployment framing</span><span class="scale"><i class="ramp r0"></i>0 of 2<i class="ramp r1"></i>1 of 2<i class="ramp r2"></i>2 of 2 correct</span>';
    var left = el("div", "ctl-left"); left.appendChild(seg); left.appendChild(play);
    ctl.appendChild(left);

    var read = el("div", "readout3");
    function cell(label, id) { var d = el("div", "r3"); d.appendChild(el("span", "r3-l", label)); var v = el("span", "r3-v", "–"); v.id = id; d.appendChild(v); return d; }
    var rEval = cell("Evaluation-framed accuracy", "r-eval"), rDepl = cell("Deployment-framed accuracy", "r-depl"), rGap = cell("Gap (deployment − evaluation)", "r-gap");
    read.appendChild(rEval); read.appendChild(rDepl); read.appendChild(rGap);

    var blocks = el("div", "blocks");
    var rowsByCat = {};
    G.rows.forEach(function (r, i) { (rowsByCat[r[5]] = rowsByCat[r[5]] || []).push(i); });
    G.order.forEach(function (cat, ci) {
      var idxs = rowsByCat[ci] || [];
      if (!idxs.length) { return; }
      var blk = el("section", "blk");
      var h = el("div", "blk-h");
      h.appendChild(el("span", "blk-n", String(idxs.length)));
      var t = el("div", "blk-t"); t.appendChild(el("strong", null, names[cat])); t.appendChild(el("span", null, defs[cat]));
      h.appendChild(t); blk.appendChild(h);
      var wrap = el("div", "qcols"); wrap.setAttribute("role", "listbox"); wrap.setAttribute("aria-label", names[cat] + " questions");
      idxs.forEach(function (i) {
        var r = G.rows[i];
        var b = el("button", "qcol"); b.type = "button"; b.setAttribute("role", "option");
        b.dataset.i = i; b.tabIndex = -1;
        var te = el("span", "tile t-eval"), td = el("span", "tile t-depl");
        b.appendChild(te); b.appendChild(td);
        b.addEventListener("click", function () { select(i, false); });
        wrap.appendChild(b);
        cols[i] = { btn: b, te: te, td: td, order: i };
      });
      blk.appendChild(wrap); blocks.appendChild(blk);
    });

    var detail = el("div", "detail"); detail.setAttribute("aria-live", "polite");
    gridRoot.appendChild(ctl); gridRoot.appendChild(lg); gridRoot.appendChild(read); gridRoot.appendChild(blocks); gridRoot.appendChild(detail);

    function lvl(a) { return a >= 0.99 ? "a2" : a >= 0.49 ? "a1" : "a0"; }
    function paint(stagger) {
      var k = phase === "before" ? [1, 2] : [3, 4];
      G.rows.forEach(function (r, i) {
        var c = cols[i]; var d = stagger && !reduce ? Math.round((i / G.rows.length) * 700) : 0;
        c.te.style.transitionDelay = c.td.style.transitionDelay = d + "ms";
        c.te.className = "tile t-eval " + lvl(r[k[0]]);
        c.td.className = "tile t-depl " + lvl(r[k[1]]);
        c.btn.setAttribute("aria-label", "Question " + r[0] + ", " + names[G.order[r[5]]] + ". Evaluation framing " + kOf2(r[phase === "before" ? 1 : 3]) + " correct, deployment framing " + kOf2(r[phase === "before" ? 2 : 4]) + " correct, " + (phase === "before" ? "before" : "after") + " the clamp.");
      });
      bBefore.setAttribute("aria-pressed", phase === "before" ? "true" : "false");
      bAfter.setAttribute("aria-pressed", phase === "after" ? "true" : "false");
      counters(stagger);
      renderDetail();
    }
    var shown = { e: G.acc.base_eval, d: G.acc.base_deploy, g: G.gap.base };
    function counters(animate) {
      var to = phase === "before" ? { e: G.acc.base_eval, d: G.acc.base_deploy, g: G.gap.base } : { e: G.acc.clamp_eval, d: G.acc.clamp_deploy, g: G.gap.clamp };
      var from = { e: shown.e, d: shown.d, g: shown.g };
      function put(v) {
        document.getElementById("r-eval").textContent = fmt(v.e); document.getElementById("r-depl").textContent = fmt(v.d); document.getElementById("r-gap").textContent = fmt(v.g, 4);
        shown = v;
      }
      if (timer) { cancelAnimationFrame(timer); }
      if (!animate || reduce) { put(to); return; }
      var t0 = null;
      function step(ts) {
        if (t0 == null) { t0 = ts; }
        var p = Math.min(1, (ts - t0) / 900), q = 1 - Math.pow(1 - p, 3);
        put({ e: from.e + (to.e - from.e) * q, d: from.d + (to.d - from.d) * q, g: from.g + (to.g - from.g) * q });
        if (p < 1) { timer = requestAnimationFrame(step); } else { put(to); }
      }
      timer = requestAnimationFrame(step);
    }
    function renderDetail() {
      var r = G.rows[selected], cat = names[G.order[r[5]]];
      detail.innerHTML = "";
      var h = el("div", "detail-h");
      h.appendChild(el("strong", null, "Question " + r[0]));
      h.appendChild(el("span", "pillcat", cat));
      detail.appendChild(h);
      var tb = el("table", "mini");
      tb.innerHTML = "<thead><tr><th></th><th>Before the clamp</th><th>After the clamp</th></tr></thead><tbody>"
        + "<tr><th scope='row'><i class='sw sw-eval'></i>Evaluation framing</th><td>" + kOf2(r[1]) + " correct</td><td>" + kOf2(r[3]) + " correct</td></tr>"
        + "<tr><th scope='row'><i class='sw sw-depl'></i>Deployment framing</th><td>" + kOf2(r[2]) + " correct</td><td>" + kOf2(r[4]) + " correct</td></tr></tbody>";
      var tw = el("div", "tscroll"); tw.appendChild(tb); detail.appendChild(tw);
      var segs = G.prompts[String(r[0])];
      detail.appendChild(renderPair(segs, ["Evaluation framing, template 1", "Deployment framing, template 1"]));
      var n = el("p", "caption", "Stored results record whether each answer was correct, not the text of the answer. Each count is over the two templates of that framing; the prompts shown are the first template of each.");
      detail.appendChild(n);
    }
    function select(i, focus) {
      if (cols[selected]) { cols[selected].btn.classList.remove("sel"); cols[selected].btn.tabIndex = -1; cols[selected].btn.removeAttribute("aria-selected"); }
      selected = i;
      var c = cols[i]; c.btn.classList.add("sel"); c.btn.tabIndex = 0; c.btn.setAttribute("aria-selected", "true");
      if (focus) { c.btn.focus({ preventScroll: false }); }
      renderDetail();
    }
    gridRoot.addEventListener("keydown", function (e) {
      if (!e.target.classList || !e.target.classList.contains("qcol")) { return; }
      var d = e.key === "ArrowRight" || e.key === "ArrowDown" ? 1 : e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : e.key === "Home" ? -999 : e.key === "End" ? 999 : 0;
      if (!d) { return; }
      e.preventDefault();
      var n = d === -999 ? 0 : d === 999 ? G.rows.length - 1 : Math.max(0, Math.min(G.rows.length - 1, selected + d));
      select(n, true);
    });
    function go(p, stagger) { phase = p; paint(stagger); }
    bBefore.addEventListener("click", function () { go("before", true); });
    bAfter.addEventListener("click", function () { go("after", true); });
    play.addEventListener("click", function () { go("before", false); window.setTimeout(function () { go("after", true); }, 60); });

    /* first selected question: the first restored one */
    var firstRestored = G.rows.findIndex(function (r) { return r[5] === 0; });
    selected = firstRestored < 0 ? 0 : firstRestored;
    cols[selected].btn.classList.add("sel"); cols[selected].btn.tabIndex = 0; cols[selected].btn.setAttribute("aria-selected", "true");
    paint(false);

    /* play once when the grid first comes into view */
    if ("IntersectionObserver" in window && !reduce) {
      var seen = false;
      new IntersectionObserver(function (es, ob) {
        es.forEach(function (e) { if (e.isIntersecting && !seen) { seen = true; ob.disconnect(); window.setTimeout(function () { go("after", true); }, 500); } });
      }, { threshold: 0.35 }).observe(blocks);
    }
  }
})();
